static int op_imm_w(TargetCoreType*c,const RiscvDecodedInsn*d){uint32 a=(uint32)c->reg.x[d->rs1],v;unsigned s=(unsigned)d->immediate&31U;if(d->aux==0)v=a+(uint32)d->immediate;else if(d->aux==1)v=a<<s;else v=(d->instruction&(1U<<30))?(uint32)((sint32)a>>s):a>>s;if(d->rd)c->reg.x[d->rd]=sext32(v);return advance(c,d);}
static int op_w(TargetCoreType*c,const RiscvDecodedInsn*d){uint32 a=(uint32)c->reg.x[d->rs1],b=(uint32)c->reg.x[d->rs2],v;unsigned s=b&31U;if(d->aux==0)v=(d->instruction&(1U<<30))?a-b:a+b;else if(d->aux==1)v=a<<s;else v=(d->instruction&(1U<<30))?(uint32)((sint32)a>>s):a>>s;if(d->rd)c->reg.x[d->rd]=sext32(v);return advance(c,d);}
static int memory_fault(TargetCoreType*c,uint64 a,uint64 cause){riscv_raise_exception(c,cause,a);c->access_fault=TRUE;return RISCV_EXEC_TRAP;}
static int load(TargetCoreType*c,const RiscvDecodedInsn*d){uint64 a=c->reg.x[d->rs1]+d->immediate,v=0;uint32 lo,hi;uint16 h;uint8 b;unsigned n,z=d->aux&15U;if(!riscv_pmp_check(c,a,z,CpuMemoryAccess_READ))return memory_fault(c,a,5);if((a&(z-1U))&&CPU_CONFIG_ERBIUM_COMPAT){for(n=0;n<z;n++){if(bus_get_data8(c->core_id,a+n,&b)!=STD_E_OK)return memory_fault(c,a,5);v|=(uint64)b<<(8U*n);}}else if(a&(z-1U))return memory_fault(c,a,4);else if(z==1){if(bus_get_data8(c->core_id,a,&b)!=STD_E_OK)return memory_fault(c,a,5);v=b;}else if(z==2){if(bus_get_data16(c->core_id,a,&h)!=STD_E_OK)return memory_fault(c,a,5);v=h;}else{if(bus_get_data32(c->core_id,a,&lo)!=STD_E_OK)return memory_fault(c,a,5);v=lo;if(z==8){if(bus_get_data32(c->core_id,a+4,&hi)!=STD_E_OK)return memory_fault(c,a,5);v|=(uint64)hi<<32;}}if(d->aux&16U)v=SEXT(v,z*8U);if(d->rd)c->reg.x[d->rd]=v;return advance(c,d);}
