static int store(TargetCoreType*c,const RiscvDecodedInsn*d){uint64 a=c->reg.x[d->rs1]+d->immediate,v=c->reg.x[d->rs2];unsigned n,z=d->aux;Std_ReturnType e=STD_E_OK;if(!riscv_pmp_check(c,a,z,CpuMemoryAccess_WRITE))return memory_fault(c,a,7);if((a&(z-1U))&&CPU_CONFIG_ERBIUM_COMPAT){for(n=0;n<z&&e==STD_E_OK;n++)e=bus_put_data8(c->core_id,a+n,(uint8)(v>>(8U*n)));}else if(a&(z-1U))return memory_fault(c,a,6);else if(z==1)e=bus_put_data8(c->core_id,a,(uint8)v);else if(z==2)e=bus_put_data16(c->core_id,a,(uint16)v);else{e=bus_put_data32(c->core_id,a,(uint32)v);if(e==STD_E_OK&&z==8)e=bus_put_data32(c->core_id,a+4,(uint32)(v>>32));}if(e!=STD_E_OK)return memory_fault(c,a,7);riscv_decode_cache_invalidate(c,a,z);return advance(c,d);}
static int system_trap(TargetCoreType*c,const RiscvDecodedInsn*d){riscv_raise_exception(c,d->instruction==MATCH_EBREAK?3:11,0);return RISCV_EXEC_TRAP;}
static int mret(TargetCoreType*c,const RiscvDecodedInsn*d){uint64 s=c->reg.csr.mstatus,t=c->reg.csr.mepc;(void)d;if(t&3U){riscv_raise_exception(c,0,t);return RISCV_EXEC_TRAP;}c->reg.privilege=(RiscvPrivilege)((s>>11)&3U);s=(s&~(1ULL<<3))|(((s>>7)&1U)<<3)|(1ULL<<7);s&=~(3ULL<<11);c->reg.csr.mstatus=s;c->reg.pc=t;return RISCV_EXEC_RETIRED;}
static int wfi(TargetCoreType*c,const RiscvDecodedInsn*d){if((c->reg.csr.mip&c->reg.csr.mie)==0)c->is_halt=TRUE;return advance(c,d);}
static int fence_i(TargetCoreType*c,const RiscvDecodedInsn*d){if(CPU_CONFIG_ERBIUM_COMPAT){riscv_raise_exception(c,30,d->instruction);return RISCV_EXEC_TRAP;}return advance(c,d);}
static uint64*csr_ptr(TargetCoreType*c,unsigned n){if(n>=0x3b0&&n<=0x3bf)return&c->reg.csr.pmpaddr[n-0x3b0];switch(n){case 0x100:return&c->reg.csr.sstatus;case 0x104:return&c->reg.csr.sie;case 0x105:return&c->reg.csr.stvec;case 0x106:return&c->reg.csr.scounteren;case 0x140:return&c->reg.csr.sscratch;case 0x141:return&c->reg.csr.sepc;case 0x142:return&c->reg.csr.scause;case 0x143:return&c->reg.csr.stval;case 0x144:return&c->reg.csr.sip;case 0x180:return&c->reg.csr.satp;case 0x300:return&c->reg.csr.mstatus;case 0x301:return&c->reg.csr.misa;case 0x302:return&c->reg.csr.medeleg;case 0x303:return&c->reg.csr.mideleg;case 0x304:return&c->reg.csr.mie;case 0x305:return&c->reg.csr.mtvec;case 0x306:return&c->reg.csr.mcounteren;case 0x30a:return&c->reg.csr.menvcfg;case 0x340:return&c->reg.csr.mscratch;case 0x341:return&c->reg.csr.mepc;case 0x342:return&c->reg.csr.mcause;case 0x343:return&c->reg.csr.mtval;case 0x344:return&c->reg.csr.mip;case 0x3a0:return&c->reg.csr.pmpcfg[0];case 0x3a2:return&c->reg.csr.pmpcfg[1];case 0xF14:return&c->reg.csr.mhartid;default:return 0;}}
